// Mimics the JS glue generated by wasm-bindgen (`--target bundler`): the wasm
// binary imports callbacks from this module, and the module-scoped `wasm`
// binding is set later through `__wbg_set_wasm`. The callbacks read from that
// binding, like wasm-bindgen glue does (e.g. `wasm.__wbindgen_externrefs`).
let wasm

export function __wbg_set_wasm(value) {
  wasm = value
}

export function __wbg_get_value() {
  return wasm.value()
}
